// The shared vectors the Solidity, Rust and TypeScript suites replay: contracts/test/vectors/propamm-v2-ladder.json,
// generated by the independent BigInt model in contracts/test/vectors/ladder-reference.mjs, or the file PROPAMM_VECTORS
// names (relative to the repository root, or absolute): a seeded random set from contracts/test/vectors/fuzz.mjs in
// the same format. The JSON's `fields` entry documents every field.
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import type { Address, Hex } from 'viem'
import { Actions, Errors, type HotWord } from '../src/index.js'

export const ROOT = fileURLToPath(new URL('../../../', import.meta.url))
export const FILE = resolve(
  ROOT,
  process.env.PROPAMM_VECTORS ??
    'contracts/test/vectors/propamm-v2-ladder.json',
)
/** The committed file, whose coverage of every outcome is asserted too; a random set is only held to the reference. */
export const committed = process.env.PROPAMM_VECTORS === undefined

/** The four taker directions, named as `ladder-reference.mjs` names them. */
export type Direction =
  | 'sellBaseExactIn'
  | 'buyBaseExactOut'
  | 'payQuoteExactIn'
  | 'wantQuoteExactOut'

/** The direction a fill walks, from `baseIn` (the taker sells base) and `exactIn` (the amount is the input). */
export const direction = (baseIn: boolean, exactIn: boolean): Direction =>
  baseIn
    ? exactIn
      ? 'sellBaseExactIn'
      : 'wantQuoteExactOut'
    : exactIn
      ? 'payQuoteExactIn'
      : 'buyBaseExactOut'

export type Vector = {
  name: string
  direction: Direction
  baseIn: boolean
  exactIn: boolean
  hot: Hex
  mid: string
  widen: string
  widthScale: string
  depthScale: string
  sizeUnit: string
  w0: Hex
  w1: Hex
  amount: string
  consumed: string
  expect: 'ok' | 'InsufficientDepth' | 'ZeroFill'
  amountIn: string
  amountOut: string
  baseFilled: string
}
export type Split = { name: string; whole: number; parts: number[] }
export type ShapeCheck = { name: string; words: Hex[]; reason: number }
export type HotWordVector = {
  name: string
  mid: string
  bidWiden: number
  askWiden: number
  widthScale: number
  depthScale: number
  shapeId: number
  validUntil: number
  seq: number
  flags: number
  word: Hex
  stored: Hex
  wellFormed: boolean
}
export type PriceVector = {
  text: string
  ok: boolean
  mid: string
  canonical: string
}
export type Ladders = {
  name: string
  bidSizes: number[]
  bidSpreads: number[]
  askSizes: number[]
  askSpreads: number[]
}
export type ShapeVector = Ladders & { words: Hex[] }
export type ShapeReject = Ladders & {
  error: 'TooManyLevels' | 'ZeroSize' | 'SpreadDecreases'
}
/** An order (optional fields absent take the defaults) or a cancel (`pairIndex`, `sequence`, `mid`). */
export type PostRequest = {
  pairIndex: number
  mid: string
  sequence: number
  shapeId?: number | undefined
  validUntil?: number | undefined
  bidWiden?: number | undefined
  askWiden?: number | undefined
  widthScale?: number | undefined
  depthScale?: number | undefined
  sides?: HotWord.Sides | undefined
  refill?: HotWord.Sides | undefined
}
export type Refusal =
  | 'EmptyBatch'
  | 'DuplicatePair'
  | 'InvalidExpiry'
  | 'InvalidSequence'
export type PostVector = {
  name: string
  kind: 'orders' | 'cancels'
  requests: PostRequest[]
  expect: 'ok' | Refusal
  packed: Hex
  calldata: Hex
  posts: [number, number][]
  stored: Hex[]
  refills: number[]
}
export type QuoteStep = {
  op: 'setShape' | 'post' | 'quote' | 'fill'
  shapeId: number
  words: Hex[]
  word: Hex
  accepted: boolean
  baseIn: boolean
  exactIn: boolean
  amount: string
  expect: string
  args: string[]
  amountIn: string
  amountOut: string
  baseFilled: string
  consumed: [string, string]
  inventory: [string, string]
}
export type QuoteCase = {
  name: string
  sizeUnit: string
  timestamp: string
  inventory: [string, string]
  steps: QuoteStep[]
}
export type Outcome = {
  accepted: [number, number][]
  skipped: [number, number][]
}
export type OutcomeVector = {
  name: string
  calls: Pick<PostVector, 'kind' | 'requests'>[]
  posted: [number, Hex][]
  outcomes: Outcome[]
}

export type Vectors = {
  postSelector: Hex
  vectors: Vector[]
  splits: Split[]
  shapeChecks: ShapeCheck[]
  hotWords: HotWordVector[]
  prices: PriceVector[]
  shapes: ShapeVector[]
  shapeRejects: ShapeReject[]
  posts: PostVector[]
  quotes: QuoteCase[]
  outcomes: OutcomeVector[]
}

export const data = JSON.parse(readFileSync(FILE, 'utf8')) as Vectors

export const ladder = (sizes: readonly number[], spreads: readonly number[]) =>
  sizes.map((size, i) => ({ size, spread: spreads[i] as number }))

/** A post request as `Post.order` takes it. */
export const orderRequest = ({ mid, ...rest }: PostRequest) => ({
  ...rest,
  mid: BigInt(mid),
  shapeId: rest.shapeId ?? 0,
  validUntil: rest.validUntil ?? 0,
})
export const cancelRequest = (q: PostRequest) => ({
  pairIndex: q.pairIndex,
  sequence: q.sequence,
  mid: BigInt(q.mid),
})

/** An order or cancel batch in the `posts` section's request form, through `Actions.maker`. */
export function postCall(
  venue: Address,
  v: Pick<PostVector, 'kind' | 'requests'>,
) {
  return v.kind === 'cancels'
    ? Actions.maker.bulkCancel.call({
        venue,
        cancels: v.requests.map(cancelRequest),
      })
    : Actions.maker.bulkOrders.call({
        venue,
        orders: v.requests.map(orderRequest),
      })
}

/** The reference's name for the SDK's refusal of a batch. */
export function refusal(error: unknown): Refusal {
  if (error instanceof Errors.EmptyBatchError) return 'EmptyBatch'
  if (error instanceof Errors.DuplicatePairError) return 'DuplicatePair'
  if (error instanceof Errors.InvalidOrderError) {
    if (error.parameter === 'sequence') return 'InvalidSequence'
    if (error.parameter === 'validUntil') return 'InvalidExpiry'
  }
  throw error
}

/** An error's arguments as the reference writes them: tokens as `base` or `quote`, the rest as decimal strings. */
export function referenceArgs(
  args: readonly unknown[],
  tokens: { base: Address; quote: Address },
): string[] {
  return args.map((a) => {
    if (typeof a === 'string' && /^0x[0-9a-fA-F]{40}$/.test(a)) {
      if (a.toLowerCase() === tokens.base.toLowerCase()) return 'base'
      if (a.toLowerCase() === tokens.quote.toLowerCase()) return 'quote'
    }
    return String(a)
  })
}
